idScanCandidates.content:
```bash
nql 1;

query GetUser(id: UserId) {
    from users as u

    where u.id == $id

    select {
        id:       u.id,
        name:     u.name,
        nickname: u.nickname
    }
}

query TeamMembers(team: TeamId) {
    from memberships as m

    join users as u
        on m.user_id == u.id

    where m.team_id == $team

    select {
        user_id: u.id,
        name:    u.name,
        role:    m.role
    }

    order {
        u.name asc
    }
}

command CreateUser(
    id: UserId,
    team: TeamId,
    name: Text,
    nickname: Text?
) {
    insert users {
        id:       $id,
        team_id:  $team,
        name:     $name,
        nickname: $nickname
    }
}

command RenameUser(
    id: UserId,
    name: Text
) {
    update users

    set {
        name = $name
    }

    where id == $id
}

command DeleteUser(id: UserId) {
    delete users
    where id == $id
}
```

supplements.content:
这种方式是不是更好？

表之间的关系不再在查询里体现，让数据库自己处理。

```bash
query UserProfile(user: UserId) {
    users[$user] {
        id
        name
        avatar

        team {
            id
            name
        }

        posts(
            published == true
            @order created_at desc
            @limit 20
        ) {
            id
            title
            created_at

            comments(
                @order created_at asc
                @limit 10
            ) {
                id
                content

                author {
                    id
                    name
                }
            }

            likes {
                count
            }
        }

        stats {
            followers
            following
            posts
        }
    }
}
```

